        daftar.add(t);
        t.setKategori(this);
    }

    void buang(Tugas t) {
        daftar.remove(t);
        t.setKategori(null);
    }

    Long getId() {
        return id;
    }

    String getNama() {
        return nama;
    }

    List<Tugas> getDaftar() {
        return daftar;
    }
}

@Entity
class Tugas {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String judul;

    @ManyToOne(fetch = FetchType.LAZY)
    private Kategori kategori;

    protected Tugas() {
    }

    Tugas(String judul) {
        this.judul = judul;
    }

    String getJudul() {
        return judul;
    }

    Kategori getKategori() {
        return kategori;
    }

    void setKategori(Kategori k) {
        kategori = k;
    }
}

class Jpa {
    static EntityManagerFactory buat(boolean tampilkanSql, Class<?>... entity) {
        Configuration cfg = new Configuration()
                .setProperty("hibernate.connection.url", "jdbc:h2:mem:toko;DB_CLOSE_DELAY=-1")
                .setProperty("hibernate.connection.username", "sa")
                .setProperty("hibernate.hbm2ddl.auto", "create")
                .setProperty("hibernate.show_sql", String.valueOf(tampilkanSql));
        for (Class<?> k : entity) {
            cfg.addAnnotatedClass(k);
        }
        return cfg.buildSessionFactory();
    }
}
